    public IList<IList<int>> CombinationSum3(int k, int n) {
        List<IList<int>> ans = new List<IList<int>>();
        for (int mask = 0; mask < 1 << 9; ++mask) {
            if (bitCount(mask) == k) {
                List<int> t = new List<int>();
                int s = 0;
                for (int i = 0; i < 9; ++i) {
                    if ((mask >> i & 1) == 1) {
                        s += i + 1;
                        t.Add(i + 1);
                    }
                }
                if (s == n) {
                    ans.Add(t);
                }
            }
        }
        return ans;
    }

    private int bitCount(int x) {
        int cnt = 0;
        while (x > 0) {
            x -= x & -x;
            ++cnt;
        }
        return cnt;
    }
}

//Editorial: https://leetcode.com/problems/combination-sum-iii/discuss/60621/My-C++-solution-backtracking
class Solution {
public:
    void solve(vector<vector<int>> &ans,vector<int> &ds,int k,int n)
    {
        if(ds.size()==k and n==0)
        {
            ans.push_back(ds);
            return;
        }
        for(int i=ds.empty()?1:ds.back()+1;i<=9;i++)
        {
            ds.push_back(i);
            solve(ans,ds,k,n-i);
            ds.pop_back();
        }
    }
    vector<vector<int>> combinationSum3(int k, int n) {
        vector<vector<int>> ans;
        vector<int> ds;
        solve(ans,ds,k,n);
        return ans;
    }
};

class Solution(object):
    def combinationSum3(self, k, n):
        """
        :type k: int
        :type n: int
        :rtype: List[List[int]]
        """

        self.result = []
        self.recurse(k, n, [], 0)
        return self.result

    def recurse(self, k, n, current, last):
        if last>9:
            return
        if k==0:
            if n==0:
                self.result.append(current)
        else:
            if n!=0:
                for num in range(last+1, 10):
                    if num>n:break
                    self.recurse(k-1, n-num, current+[num], num)

